#define STR_SETTINGS_ENABLE_FX          NSLS(@"settings.playback.enable_fx",                    @"Audio effects",          @"Settings, Playback, on both platforms: checkbox (macOS) or switch (iOS) choosing whether the DJ performance effects (low kill, reverb, delay) are available. 'FX' is the DJ term for effects, left untranslated.")
#define STR_SETTINGS_CROSSFADE_CAPTION NSLS(@"settings.playback.crossfade.caption", @"Blend the end of each track into the next", @"Settings, Playback pane: caption under the Crossfade slider.")
