#define STR_LINK_ERROR_NOT_FOUND      NSLS(@"link.error.not_found",      @"There’s no file at that address. Check the address and try again.", @"Open URL error: the server answered that nothing exists at the address (HTTP 404).")
#define STR_LINK_ERROR_DENIED         NSLS(@"link.error.denied",         @"The server didn’t allow access to that file. The link may be private or expired.", @"Open URL error: the server refused to send the file (HTTP 401 or 403), for example a private or expired share link.")
#define STR_LINK_ERROR_NOT_AUDIO      NSLS(@"link.error.not_audio",      @"That address doesn’t lead to an audio file Vibe can play.", @"Open URL error: the address leads to something else, such as a web page. Vibe is the app name.")
#define STR_LINK_ERROR_NO_SIZE        NSLS(@"link.error.no_size",        @"The server doesn’t say how big the file is. Vibe needs the size to play it.", @"Open URL error: the server sent the file without its size, which Vibe needs in order to stream and seek. Vibe is the app name.")
#define STR_LINK_ERROR_LIVE_STREAM    NSLS(@"link.error.live_stream",    @"Live streams and internet radio aren’t supported. Enter the address of an audio file.", @"Open URL error: the address is a live broadcast that never ends, such as an internet radio station, rather than a file.")
