#define STR_LABEL_EMPTY_MESSAGE NSLS(@"label.library.empty.message", @"Choose a folder or file to get started.", @"iOS: explanatory line under the empty library headline, above the Open button.")

#define STR_LABEL_FAVORITES_EMPTY_TITLE   NSLS(@"label.favorites.empty.title",   @"No Favorites", @"iOS: headline of the empty favorites screen, shown when the user has not starred any folder yet.")
#define STR_LABEL_FAVORITES_EMPTY_MESSAGE NSLS(@"label.favorites.empty.message", @"Add a folder from the Files tab, or star the one you have open, to keep it here.", @"iOS: explanatory line under the empty favorites headline. It names both ways to make a favorite, each in the words its own screen uses: the Files tab's long-press menu item says 'Add to Favorites', while the playlist screen's control is a star. 'Here' is the Favorites tab the line is shown on.")
#define STR_ERROR_FAVORITE_UNAVAILABLE    NSLS(@"error.favorite.unavailable",    @"This folder can’t be opened right now. It may have been moved or deleted, or its cloud service may be signed out.", @"iOS: alert message shown when tapping a favorite whose folder could not be found. The alert’s title is the folder’s name. Uses a curly apostrophe (’).")

#define STR_MENU_PLAYLIST_CLEAR          NSLS(@"menu.playlist.clear",          @"Clear Playlist",        @"iOS: destructive menu item on the playlist screen's bar button; empties the playlist and stops playback. It deletes no files — it only unloads what is queued — so the wording says Clear rather than Delete.")

#define STR_MENU_CONTEXT_PLAY            NSLS(@"menu.context.play",            @"Play",                  @"iOS: long-press menu item on a Favorites row, where it opens the starred folder as the playlist and starts playing it, and on a file in the search results, where it plays that one file alone. Either way it replaces whatever was queued — the same as tapping the row.")
#define STR_MENU_CONTEXT_OPEN_FOLDER     NSLS(@"menu.context.open_folder",     @"Open Folder",           @"iOS: long-press menu item on a search result or a Recents row. Shows the folder in the Files tab — the folder holding a file, or the folder itself — without playing anything.")
#define STR_MENU_CONTEXT_PLAY_IN_FOLDER  NSLS(@"menu.context.play_in_folder",  @"Play in Folder",        @"iOS: long-press menu item on a file in the search results. Opens the folder holding the file as the playlist and starts playing from that file, replacing whatever was queued. Its neighbour 'Play' plays the file alone.")
#define STR_MENU_CONTEXT_ADD_TO_PLAYLIST NSLS(@"menu.context.add_to_playlist", @"Add to Playlist",       @"iOS: long-press menu item and swipe action on a Favorites row, the long-press action on a file or folder in the Files tab, and the accessibility label of the playlist screen's plus button, which opens the system picker. Adds tracks to the end of the playlist without interrupting what is playing.")
#define STR_MENU_CONTEXT_ADD_FAVORITE    NSLS(@"menu.context.add_favorite",    @"Add to %@ Favorites",   @"iOS: long-press menu item on a FOLDER in the Files tab; stars it so it appears on the Favorites tab, without opening it or changing the playlist. %@ is the app name. It is named because the system's own 'Favorite' item sits in the same menu, and without it the two read as near-duplicates and neither says whose favorites it means. Keep the %@ — the app name is not translated, but the grammar around it is.")
#define STR_MENU_CONTEXT_REMOVE_FAVORITE NSLS(@"menu.context.remove_favorite", @"Remove from Favorites", @"iOS: destructive long-press menu item on a Favorites row, and the accessibility label of the playlist screen's star button when the open folder is already starred. Both take the folder off the Favorites tab.")

#define STR_A11Y_PLAYER_MINIMIZE   NSLS(@"a11y.player.minimize",   @"Minimize",     @"iOS: accessibility label for the full-screen player's grabber, which returns it to the mini player strip.")
#define STR_A11Y_PLAYER_OUTPUT_ROUTE NSLS(@"a11y.player.output_route", @"Output Device", @"iOS: accessibility label for the button on the full-screen player that opens the system list of AirPlay and Bluetooth devices to play through.")
#define STR_A11Y_PLAYER_FX_PAD     NSLS(@"a11y.player.fx_pad",     @"Effects pad",  @"iOS: accessibility label for the FX pad on the full-screen player — a touch pad that applies DJ effects (a low-cut filter, reverb, delay) while a finger holds it.")
#define STR_A11Y_PLAYER_FX_PAD_HINT NSLS(@"a11y.player.fx_pad_hint", @"Touch and drag. Up cuts the bass, right adds reverb and then delay. Lift to release.", @"iOS: accessibility hint for the FX pad on the full-screen player, explaining the drag: the vertical axis is a low-cut filter, the horizontal axis adds reverb then delay, and lifting the finger turns every effect off.")
#define STR_PLAYER_FX_PILL         NSLS(@"player.fx_pill",         @"FX",           @"iOS: the label on the small round button in the full-screen player's bottom bar that opens the effects pad when touched. 'FX' is the DJ term for effects; keep it very short — the button is a 56-point circle.")
#define STR_PLAYER_FX_AXIS_LOW_CUT NSLS(@"player.fx_axis.low_cut", @"LOW CUT ↑",    @"iOS: caption in the top-left corner of the effects pad naming its vertical axis: dragging up raises a low-cut (high-pass) filter that removes the bass. Keep the arrow; upper case is the pad's style.")
#define STR_PLAYER_FX_AXIS_REVERB_DELAY NSLS(@"player.fx_axis.reverb_delay", @"REVERB → DELAY", @"iOS: caption in the bottom-right corner of the effects pad naming its horizontal axis: dragging right adds reverb, and past the middle a beat-synced delay (echo) on top. Keep the arrow; upper case is the pad's style.")
#define STR_A11Y_ADD_FAVORITE      NSLS(@"a11y.favorite.add",      @"Add to Favorites",      @"iOS: accessibility label for the star button on the playlist screen, when the open folder is not starred yet; activating it adds the folder to the Favorites tab.")
#define STR_A11Y_PLAYLIST_MENU     NSLS(@"a11y.playlist.menu",     @"Options",               @"iOS: accessibility label for the gear button on the playlist screen's bar. It no longer opens Settings directly — it opens a menu holding Settings and Clear Playlist — so the label names the menu rather than either item.")


